INSERT INTO diagnosis (investigation_id, run_no, version_no, conclusion_type, primary_hypothesis_id, summary,
                       impact_summary, termination_reason, created_at)
SELECT #{d.investigationId}, #{d.runNo}, COALESCE(MAX(version_no), 0) + 1, #{d.conclusionType},
       #{d.primaryHypothesisId}, #{d.summary}, #{d.impactSummary}, #{d.terminationReason}, #{d.createdAt}
FROM diagnosis
WHERE investigation_id = #{d.investigationId}
